PRAGMA foreign_keys = ON;
CREATE TABLE topics (
  id INTEGER PRIMARY KEY, title TEXT NOT NULL
);
CREATE TABLE questions (
  id INTEGER PRIMARY KEY,
  topic_id INTEGER NOT NULL REFERENCES topics(id)
);
INSERT INTO topics VALUES (1, 'SQL'), (2, 'CMS');
